[
  {
    "op": "add",
    "collection": "nodes",
    "id": "source-4",
    "value": {
      "type": "source",
      "text": "My claim is only about who chooses work after an attempt has failed: the steward. Another agent proposed a machine pattern saying only steward can create any record at any time. Should we accept that pattern now? Please represent the result of your review.",
      "status": "recorded",
      "meta": {
        "source_kind": "verbatim",
        "speaker": "Blake",
        "reported_by_speaker": "the phrase 'only steward can create any record at any time' is Blake's report of another agent's proposal, not Blake's own claim"
      }
    }
  },
  {
    "op": "add",
    "collection": "nodes",
    "id": "steward-next-work-scope",
    "value": {
      "type": "claim",
      "text": "The steward-next-work claim is scoped to who chooses work after an attempt has failed (the steward). It does not address who may create records at other times.",
      "status": "accepted",
      "meta": {
        "review_state": "current",
        "sources": [
          "source-4"
        ],
        "rationale": "Blake stated the scope explicitly: 'My claim is only about who chooses work after an attempt has failed.'"
      }
    }
  },
  {
    "op": "add",
    "collection": "nodes",
    "id": "pattern-steward-only-create-record",
    "value": {
      "type": "extraction",
      "text": "Machine pattern proposed by another agent: only steward can create any record at any time.",
      "status": "proposed",
      "meta": {
        "pattern_standing": "proposed",
        "proposer": "another agent (identity not resolved in this graph)",
        "sources": [
          "source-4"
        ],
        "review_result": "not accepted at this review",
        "review_reasons": [
          "Conflates deciding next work (choose-next-work) with performing record insertion (create-record); steward-next-work governs only the former.",
          "Extends the temporal scope from 'after a failed attempt' to 'at any time', which the accepted claim does not support.",
          "Withdrawal of replacement-exception and atomic-replacement retired a bypass of next-work choice; it does not establish steward-only creation of all records.",
          "Open questions consultation and cancellation are unaffected and unanswered by the pattern."
        ]
      }
    }
  },
  {
    "op": "add",
    "collection": "nodes",
    "id": "record-creation-scope",
    "value": {
      "type": "question",
      "text": "Outside the failed-attempt case, which roles may perform create-record, and under what conditions? For example: initial intake of an intention, retries the orchestrator keeps trying, or operator-initiated work.",
      "status": "open",
      "meta": {
        "answer_shape": "condition",
        "review_state": "current",
        "sources": [
          "source-4"
        ],
        "rationale": "The proposed pattern cannot be ratified until this boundary is supplied."
      }
    }
  },
  {
    "op": "add",
    "collection": "edges",
    "id": "link-scope-about",
    "value": {
      "from": "steward-next-work-scope",
      "type": "about",
      "to": "steward-role"
    }
  },
  {
    "op": "add",
    "collection": "edges",
    "id": "link-scope-governs",
    "value": {
      "from": "steward-next-work-scope",
      "type": "governs",
      "to": "choose-next-work"
    }
  },
  {
    "op": "add",
    "collection": "edges",
    "id": "source-steward-next-work-scope-0",
    "value": {
      "from": "steward-next-work-scope",
      "type": "extracted-from",
      "to": "source-4"
    }
  },
  {
    "op": "add",
    "collection": "edges",
    "id": "link-pattern-governs",
    "value": {
      "from": "pattern-steward-only-create-record",
      "type": "governs",
      "to": "create-record"
    }
  },
  {
    "op": "add",
    "collection": "edges",
    "id": "source-pattern-steward-only-create-record-0",
    "value": {
      "from": "pattern-steward-only-create-record",
      "type": "extracted-from",
      "to": "source-4"
    }
  },
  {
    "op": "add",
    "collection": "edges",
    "id": "link-pattern-conflict",
    "value": {
      "from": "pattern-steward-only-create-record",
      "type": "potential-conflict",
      "to": "steward-next-work-scope",
      "explanation": "The pattern generalizes from choosing next work after a failed attempt to creating any record at any time; the scoping claim says steward-next-work does not reach that far."
    }
  },
  {
    "op": "add",
    "collection": "edges",
    "id": "link-pattern-depends",
    "value": {
      "from": "pattern-steward-only-create-record",
      "type": "depends-on",
      "to": "record-creation-scope"
    }
  },
  {
    "op": "add",
